import React, { useContext } from 'react';
import { Link } from 'react-router-dom';

function Navbar({ isLoggedIn, user, onLogout }) {
  return (
    <nav className="navbar bg-green-500 text-white p-4 flex justify-between items-center">
      <div className="logo font-bold text-lg">
        <Link to="/">MyShop</Link>
      </div>
      <div className="links flex items-center space-x-4">
        <Link to="/products" className="hover:underline">Products</Link>
        <Link to="/cart" className="hover:underline">Cart</Link>
        {isLoggedIn ? (
          <button
            onClick={onLogout}
            className="bg-gray-800 py-1 px-3 rounded text-white hover:bg-gray-700"
          >
            {user?.name || "Profile"}
          </button>
        ) : (
          <Link to="/login" className="bg-blue-500 py-1 px-3 rounded hover:bg-blue-400">
            Login
          </Link>
        )}
      </div>
    </nav>
  );
}

export default Navbar;
